import{_ as r,a,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"Redis 原理深入","description":"从数据类型与编码、执行模型、内存淘汰、持久化到复制与集群，理解 Redis 的性能与可靠性边界。","frontmatter":{"title":"Redis 原理深入","description":"从数据类型与编码、执行模型、内存淘汰、持久化到复制与集群，理解 Redis 的性能与可靠性边界。","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","summary":"从数据类型与编码、执行模型、内存淘汰、持久化到复制与集群，理解 Redis 的性能与可靠性边界。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Redis 知识复盘","link":"/middleware/redis/pro/interview/redis-%E9%9D%A2%E8%AF%95"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Redis 知识复盘","link":"/middleware/redis/pro/interview/redis-%E9%9D%A2%E8%AF%95"}},"headers":[],"relativePath":"middleware/redis/pro/principles/mechanisms.md","filePath":"middleware/redis/pro/principles/mechanisms.md"}'),s={name:"middleware/redis/pro/principles/mechanisms.md"};function d(n,e,o,l,p,c){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="redis-原理深入" tabindex="-1">Redis 原理深入 <a class="header-anchor" href="#redis-原理深入" aria-label="Permalink to &quot;Redis 原理深入&quot;">​</a></h1><p>掌握 <a href="/middleware/redis/base/basic/overview">base 基础</a> 和 <a href="/middleware/redis/plus/subjects/types">plus 数据类型</a> 后，可以沿着“数据怎么存、命令怎么执行、故障后留下什么”理解原理。</p><h2 id="数据类型与底层编码" tabindex="-1">数据类型与底层编码 <a class="header-anchor" href="#数据类型与底层编码" aria-label="Permalink to &quot;数据类型与底层编码&quot;">​</a></h2><p>数据类型决定命令语义，编码决定内部表示。同一种类型可能因数据量、元素大小、配置或版本使用不同编码。不能把“Hash 类型”直接等同于“始终采用哈希表”，也不能把内部结构名称当成新的一种业务类型。</p><p>可在实验服务用 <code>TYPE key</code> 查看类型，用 <code>OBJECT ENCODING key</code> 观察编码，用 <code>MEMORY USAGE key</code> 估算该键占用。比较时同时记录版本、元素数量与大小，不能仅凭一个小样本推断所有数据的内存成本。</p><p>参考：<a href="https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/memory-optimization/" target="_blank" rel="noopener noreferrer">内存优化</a>、<a href="https://redis.io/docs/latest/commands/object-encoding/" target="_blank" rel="noopener noreferrer">OBJECT ENCODING</a>。</p><h2 id="执行模型与延迟" tabindex="-1">执行模型与延迟 <a class="header-anchor" href="#执行模型与延迟" aria-label="Permalink to &quot;执行模型与延迟&quot;">​</a></h2><p>命令执行、网络 I/O、后台持久化和内存释放属于不同工作。分析性能时，应区分服务端处理耗时与客户端观察到的总耗时；网络、连接等待和返回数据大小也会影响延迟。</p><p>先检查慢命令、大量返回和长脚本，再结合客户端指标定位。Pipeline 减少往返次数，但不会降低单条复杂命令本身的计算成本，也不提供事务隔离。</p><p>继续阅读：<a href="/middleware/redis/pro/interview/redis-面试#execution">执行模型与慢请求</a>、<a href="/middleware/redis/plus/troubleshooting/diagnostics">延迟与内存排查</a>。</p><h2 id="过期与内存淘汰" tabindex="-1">过期与内存淘汰 <a class="header-anchor" href="#过期与内存淘汰" aria-label="Permalink to &quot;过期与内存淘汰&quot;">​</a></h2><p>过期解决数据的时间有效性，淘汰解决达到内存限制时如何腾出空间。设置了 TTL 的键可能在到期之前因淘汰被删除；没有 TTL 的键也不意味着能在所有淘汰策略下永久保留。</p><p><code>maxmemory</code> 和策略需要匹配业务用途。可重建缓存与不能随意丢失的限额、锁状态，往往需要不同的容量与隔离策略。选择 <code>noeviction</code> 也需要应用处理写入失败，不能把失败留给业务偶然发现。</p><p>参考：<a href="https://redis.io/docs/latest/develop/reference/eviction/" target="_blank" rel="noopener noreferrer">内存淘汰</a>。</p><h2 id="持久化与恢复代价" tabindex="-1">持久化与恢复代价 <a class="header-anchor" href="#持久化与恢复代价" aria-label="Permalink to &quot;持久化与恢复代价&quot;">​</a></h2><p>快照和 AOF 都会引入磁盘、内存和后台任务成本。理解它们时要分别检查写入成功、同步磁盘、备份生成和恢复完成这几个时刻；客户端收到成功响应，不代表独立备份已经包含该写入。</p><p>继续阅读：<a href="/middleware/redis/plus/practice/operations#persistence">RDB 与 AOF 的恢复边界</a> 和 <a href="/middleware/redis/plus/practice/operations#restore">独立恢复实验</a>。</p><h2 id="复制、sentinel-与-cluster" tabindex="-1">复制、Sentinel 与 Cluster <a class="header-anchor" href="#复制、sentinel-与-cluster" aria-label="Permalink to &quot;复制、Sentinel 与 Cluster&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>主要解决的问题</th><th>必须考虑的边界</th></tr></thead><tbody><tr><td>主从复制</td><td>将主节点的变化传播给副本</td><td>通常异步，读副本可能看到旧数据，切换可能丢失未复制写入</td></tr><tr><td>Sentinel</td><td>非 Cluster 部署中的监控与自动故障切换</td><td>不负责把数据分片；客户端需要支持发现当前主节点</td></tr><tr><td>Cluster</td><td>按哈希槽分布数据并管理节点故障</td><td>多键操作通常要求同槽，客户端需要处理重定向</td></tr></tbody></table><p>复制不能替代备份，自动切换也不能直接推导出强一致或零数据丢失。学习时应画出“写主节点 → 复制 → 主节点故障 → 副本接管”的时序，检查各时刻哪些数据可能尚未传播。</p><p>本页说明机制，不包含已执行的多节点部署实验。实际搭建需要按版本文档确认拓扑、网络、客户端与恢复方案。</p><p>参考：<a href="https://redis.io/docs/latest/operate/oss_and_stack/management/replication/" target="_blank" rel="noopener noreferrer">复制</a>、<a href="https://redis.io/docs/latest/operate/oss_and_stack/management/sentinel/" target="_blank" rel="noopener noreferrer">Sentinel</a>、<a href="https://redis.io/docs/latest/operate/oss_and_stack/reference/cluster-spec/" target="_blank" rel="noopener noreferrer">Cluster</a>。</p>',22)])])}const u=r(s,[["render",d]]);export{m as __pageData,u as default};
